// Manual runs are always mode 'manual' (§6.1, §6.5) and bypass the TASE-hours
// gate - the demo must run on demand regardless of the clock.
return [{ json: { mode: 'manual' } }];

// Chat-initiated runs (§6.5). `tickers` is an optional comma-separated string
// supplied by the chat assistant's Call n8n Workflow Tool; when present it
// overrides the config watchlist for this run only (/runs/start, §5), so an
// ad-hoc single-ticker request reuses this identical pipeline. Omitted =>
// the full watchlist, exactly like a manual run.
//
// Like the manual path, chat bypasses the TASE-hours gate: an on-demand
// question should answer whatever the clock says.
const raw = $json.tickers;
const tickers = String(raw == null ? '' : raw)
  .split(',')
  .map((t) => t.trim())
  .filter((t) => t.length > 0);
return [{ json: { mode: 'chat', tickers: tickers.length ? tickers : null } }];

// TASE trading-hours gate (§6.1, §11.2). Sun-Thu, 09:30-17:30 Asia/Jerusalem.
// The schedule_cron (config/universe.yaml §4.4) already fires only Sun-Thu
// 10:00-17:00 local, but this is an INDEPENDENT in-workflow check so a stray
// out-of-hours fire exits cleanly with NO runs row written (§11.2). It sits
// before /runs/start, which is the only thing that mints a runs row.
//
// DEV OVERRIDE (not in the design; test-only): if $env.TASE_GATE_FAKE_NOW holds
// an ISO timestamp, the gate evaluates that instant instead of the real clock so
// the outside-hours branch is deterministically verifiable. MUST be unset in
// production.
const fake = ($env.TASE_GATE_FAKE_NOW || '').trim();
const now = fake ? new Date(fake) : new Date();
if (isNaN(now.getTime())) {
  throw new Error('TASE_GATE_FAKE_NOW is set but not a valid ISO timestamp: ' + fake);
}

// Wall-clock parts in Asia/Jerusalem, independent of the server's own timezone
// (§11.2: render Asia/Jerusalem). hourCycle h23 keeps midnight as 00, not 24.
const parts = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Asia/Jerusalem',
  weekday: 'short',
  hour: '2-digit',
  minute: '2-digit',
  hourCycle: 'h23',
}).formatToParts(now);
const get = (t) => (parts.find((p) => p.type === t) || {}).value;
const weekday = get('weekday');
const hh = get('hour');
const mm = get('minute');
const minutes = parseInt(hh, 10) * 60 + parseInt(mm, 10);

const OPEN = 9 * 60 + 30;   // 09:30
const CLOSE = 17 * 60 + 30; // 17:30
const tradingDay = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu'].includes(weekday);
const within_tase_hours = tradingDay && minutes >= OPEN && minutes <= CLOSE;

return [{
  json: {
    within_tase_hours,
    checked_at_il: weekday + ' ' + hh + ':' + mm + ' Asia/Jerusalem',
    fake_now: fake || null,
  },
}];

// One item per ticker. The watchlist and the window parameters come from
// /runs/start (config/universe.yaml, §4.4) — never hardcoded in the workflow.
const run = $json;
const watchlist = run.watchlist || [];
if (!watchlist.length) {
  throw new Error('/runs/start returned an empty watchlist - check config/universe.yaml (4.4)');
}
return watchlist.map((ticker) => ({
  json: {
    run_id: run.run_id,
    ticker,
    window_minutes: run.window_minutes,
    window_days: run.window_days,
    lookback_days: run.lookback_days,
  },
}));

// Namespace the agent output: the three agents share keys (ticker, status,
// summary), which a positional merge would otherwise clobber.
return $input.all().map((item) => ({ json: { technical: item.json } }));

// Risk Manager input (§6.2): the three agent outputs for one ticker.
// agent_status (§4.2) is captured HERE, from the agents' own outputs — the Risk
// Manager echoes back only the §6.3 summary panels, which carry no `status`.
const runId = $('Start Run').first().json.run_id;
return $input.all().map((item) => {
  const technical = item.json.technical || {};
  const sentiment = item.json.sentiment || {};
  const earnings = item.json.earnings || {};
  const ticker = technical.ticker || sentiment.ticker || earnings.ticker;
  if (!ticker) {
    throw new Error('merged agent outputs carry no ticker - check the agent fan-out');
  }
  const agent_status = {
    sentiment: sentiment.status || 'degraded',
    earnings: earnings.status || 'degraded',
    technical: technical.status || 'degraded',
  };
  return { json: { run_id: runId, ticker, sentiment, earnings, technical, agent_status } };
});

// The store call's response ({stored:1}) replaced the items, so re-emit the Risk
// Manager outputs before looping back - they are what the report is built from.
return $('Risk Manager').all().map((item) => ({ json: item.json }));

const start = $('Start Run').first().json;
const recommendations = $input.all().map((i) => i.json).filter((r) => r && r.ticker);
const counts = {};
for (const rec of recommendations) {
  const call = (rec.final && rec.final.recommendation) || 'unknown';
  counts[call] = (counts[call] || 0) + 1;
}
const summary = Object.entries(counts).map((entry) => entry[1] + ' ' + entry[0]).join(', ') || 'no recommendations';
return [{ json: { run_id: start.run_id, recommendations, summary } }];

// Run status (§9.4): a degraded agent or a degraded cost harvest degrades the run;
// a missing report path is an error. No silent fallbacks.
const start = $('Start Run').first().json;
const payload = $('Build Report Payload').first().json;
const report = $('Render Report').first().json || {};
const harvest = $json || {};

const recommendations = payload.recommendations || [];
const anyDegraded = recommendations.some((rec) =>
  rec.status === 'degraded' ||
  ['sentiment', 'earnings', 'technical'].some((k) => rec[k] && rec[k].status === 'degraded')
);
const reportPath = report.pdf_path || null;
const harvestDegraded = String(harvest.summary || '').startsWith('degraded');

let status = 'ok';
if (!reportPath) {
  status = 'error';
} else if (anyDegraded || harvestDegraded) {
  status = 'degraded';
}

return [{
  json: {
    run_id: start.run_id,
    status,
    report_path: reportPath,
    tickers: recommendations.length,
    cost_summary: harvest.summary || null,
  },
}];

// Tool result for the §6.5 chat assistant. This is the workflow's LAST node, so
// its output is exactly what the Call n8n Workflow Tool hands back to the chat
// agent — and the chat agent is a router with no analytical authority, so every
// number and verdict it is allowed to say must appear HERE, verbatim from the
// Risk Manager's final pass. Nothing is summarised or re-worded by an LLM on the
// way out. Harmless for manual/scheduled runs, which simply ignore it.
const assess = $('Assess Run').first().json;
const payload = $('Build Report Payload').first().json;

const results = (payload.recommendations || []).map((rec) => {
  const final = rec.final || {};
  const agentStatus = ['sentiment', 'earnings', 'technical'].filter(
    (k) => rec[k] && rec[k].status === 'degraded'
  );
  return {
    ticker: rec.ticker,
    recommendation: final.recommendation || 'unavailable',
    conviction: final.conviction || 'unavailable',
    rationale: final.rationale || 'unavailable',
    degraded_agents: agentStatus,
  };
});

return [{
  json: {
    run_id: assess.run_id,
    status: assess.status,
    report_path: assess.report_path,
    results,
    summary: payload.summary,
  },
}];
